create table if not exists public.clinical_encounter_case_versions (id uuid primary key default gen_random_uuid(),case_id text not null,version text not null,state text not null check(state in('draft','published','archived')),truth jsonb not null,reference_path jsonb not null default '[]'::jsonb,media_attested boolean not null default false,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz,unique(case_id,version));
alter table public.clinical_encounter_case_versions enable row level security;
create policy "clinical_encounter_cases_read_published" on public.clinical_encounter_case_versions for select to authenticated using(state='published');
create policy "clinical_encounter_cases_author_write" on public.clinical_encounter_case_versions for all to authenticated using(exists(select 1 from public.bty_platform_admin_grants g where g.user_id=auth.uid() and g.status='active')) with check(exists(select 1 from public.bty_platform_admin_grants g where g.user_id=auth.uid() and g.status='active'));
